230: static std::string* RangeOption (napi_env env, napi_value opts, const char* name) {
231:   if (HasProperty(env, opts, name)) {
232:     napi_value value = GetProperty(env, opts, name);
233: 
234:     if (StringOrBufferLength(env, value) > 0) {
235:       LD_STRING_OR_BUFFER_TO_COPY(env, value, to);
236:       std::string* result = new std::string(toCh_, toSz_);
237:       delete [] toCh_;
238:       return result;
239:     }
240:   }
241: 
242:   return NULL;
243: }
244: 
245: /**
246:  * Converts an array containing Buffer or string keys to a vector.
247:  * Empty elements are skipped.
248:  */
249: static std::vector<std::string>* KeyArray (napi_env env, napi_value arr) {
250:   uint32_t length;
251:   std::vector<std::string>* result = new std::vector<std::string>();
252: 
253:   if (napi_get_array_length(env, arr, &length) == napi_ok) {
254:     result->reserve(length);
255: 
256:     for (uint32_t i = 0; i < length; i++) {
257:       napi_value element;
258: 
259:       if (napi_get_element(env, arr, i, &element) == napi_ok &&
260:           StringOrBufferLength(env, element) > 0) {
261:         LD_STRING_OR_BUFFER_TO_COPY(env, element, to);
262:         result->emplace_back(toCh_, toSz_);
263:         delete [] toCh_;
264:       }
265:     }
266:   }
267: 
268:   return result;
269: }
