271: /**
272:  * Calls a function.
273:  */
274: static napi_status CallFunction (napi_env env,
275:                                  napi_value callback,
276:                                  const int argc,
277:                                  napi_value* argv) {
278:   napi_value global;
279:   napi_get_global(env, &global);
280:   return napi_call_function(env, global, callback, argc, argv, NULL);
281: }
