292: /**
293:  * Helper struct for caching and converting a key-value pair to napi_values.
294:  */
295: struct Entry {
296:   Entry (const leveldb::Slice* key, const leveldb::Slice* value) {
297:     key_ = key != NULL ? new std::string(key->data(), key->size()) : NULL;
298:     value_ = value != NULL ? new std::string(value->data(), value->size()) : NULL;
299:   }
300: 
301:   ~Entry () {
302:     if (key_ != NULL) delete key_;
303:     if (value_ != NULL) delete value_;
304:   }
305: 
306:   // Not used yet.
307:   void ConvertXX (napi_env env, Mode mode, bool keyAsBuffer, bool valueAsBuffer, napi_value* result) {
308:     if (mode == Mode::entries) {
309:       napi_create_array_with_length(env, 2, result);
310: 
311:       napi_value valueElement;
312:       napi_value keyElement;
313: 
314:       Convert(env, key_, keyAsBuffer, &keyElement);
315:       Convert(env, value_, valueAsBuffer, &valueElement);
316: 
317:       napi_set_element(env, *result, 0, keyElement);
318:       napi_set_element(env, *result, 1, valueElement);
319:     } else if (mode == Mode::keys) {
320:       Convert(env, key_, keyAsBuffer, result);
321:     } else {
322:       Convert(env, value_, valueAsBuffer, result);
323:     }
324:   }
325: 
326:   static void Convert (napi_env env, const std::string* s, bool asBuffer, napi_value* result) {
327:     if (s == NULL) {
328:       napi_get_undefined(env, result);
329:     } else if (asBuffer) {
330:       napi_create_buffer_copy(env, s->size(), s->data(), NULL, result);
331:     } else {
332:       napi_create_string_utf8(env, s->data(), s->size(), result);
333:     }
334:   }
335: 
336: private:
337:   std::string* key_;
338:   std::string* value_;
339: };
