  const bool fillCache = BooleanProperty(env, options, "fillCache", true);
  napi_value callback = argv[3];

  GetManyWorker* worker = new GetManyWorker(
    env, database, keys, callback, asBuffer, fillCache
  );

  worker->Queue(env);
  NAPI_RETURN_UNDEFINED();
}

